  "parecer": "sustentada",
  "tipo_efeito": "confirmacao_local",
  "aspectos": {
    "entidade": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D08",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D08 identifica SUP_MOTOR como objeto da disponibilidade contratada; N.SUP_MOTOR identifica SUP_MOTOR como o Fornecedor MotorTech."
    },
    "alvo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D08",
        "N.SUP_MOTOR"
      ],
      "justificativa": "N.SUP_MOTOR define para SUP_MOTOR a restrição «não antes de D18». CHANGE.D08 confirma a disponibilidade contratada de 18 dias corridos desde D0, compatível com esse alvo."
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": [
        "N.SUP_MOTOR",
        "CHANGE.D08"
      ],
      "justificativa": "N.SUP_MOTOR explicita que a disponibilidade contratada do fornecedor é representada por um ponto de disponibilidade, com duração zero, e por uma restrição de não início antes de D18. CHANGE.D08 confirma o parâmetro de disponibilidade."
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D08",
        "N.SUP_MOTOR"
      ],
      "justificativa": "As fontes expressam o prazo em dias corridos."
    },
    "valor": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D08",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D08 informa 18 dias corridos desde D0; N.SUP_MOTOR registra a restrição local vigente como não antes de D18. A proposta de valor 18 é compatível e confirma esse valor local."
    },
    "condicoes": {
      "estado": "nao_aplicavel",
      "fonte_ids": [],
      "justificativa": "A proposta não especifica condições de aplicação."
    },
    "escopo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D08"
      ],
      "justificativa": "O evento situa a disponibilidade prospectivamente desde D0 e limita o escopo ao universo sintético Alfa v1, compatível com o escopo da proposta."
    }
  },
  "fontes_examinadas": [
    "CHANGE.D08",
    "N.SUP_MOTOR"
  ],
  "justificativa": "As fontes originais sustentam a entidade, o alvo de restrição local, o atributo, a unidade, o valor e o escopo. A proposta cita CHANGE.D08, cuja informação está coberta. O evento confirma a disponibilidade contratada de 18 dias desde D0, consistente com a restrição local vigente de não antes de D18; portanto, o efeito avaliado é uma confirmação local.",
  "suporte_ausente": []
}
